h=w=28
seps={4,9,14,19,24}
# Mark panel-cell colors, with mixed-color crossings shown as 6.
panel_colors={}
def paint(r,c,color):
    panel_colors[(r,c)] = color if (r,c) not in panel_colors or panel_colors[(r,c)]==color else 6
for r in range(0,5): paint(r,2,3) # join the aligned 3 markers
for c in range(0,5): paint(1,c,2) # join the aligned 2 markers
for r in range(1,4): paint(r,0,2) # join the aligned 2 markers
# build panel bounds
bounds=[]
start=0
for i in range(h):
    if i in seps:
        if start<i: bounds.append((start,i))
        start=i+1
if start<h: bounds.append((start,h))
cbounds=[]
start=0
for i in range(w):
    if i in seps:
        if start<i: cbounds.append((start,i))
        start=i+1
if start<w: cbounds.append((start,w))
grid=[[8 if r in seps or c in seps else 0 for c in range(w)] for r in range(h)]
for (pr,(r0,r1)) in enumerate(bounds):
    for (pc,(c0,c1)) in enumerate(cbounds):
        color=panel_colors.get((pr,pc),0)
        if color:
            for r in range(r0,r1):
                for c in range(c0,c1): grid[r][c]=color
import json
print(json.dumps(grid,separators=(',',':')))

